    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    rows = [[c for c in range(w) if grid[r][c] != background] for r in range(h)]
    cols = [[r for r in range(h) if grid[r][c] != background] for c in range(w)]

    # Bridge short gaps between consecutive markers on each straight line.
    for r, marks in enumerate(rows):
        for a, b in zip(marks, marks[1:]):
            if b - a <= 7:
                for c in range(a + 1, b):
                    out[r][c] = 2

    for c, marks in enumerate(cols):
        for a, b in zip(marks, marks[1:]):
            if b - a <= 7:
                for r in range(a + 1, b):
                    out[r][c] = 2

    # Join nearby horizontal and vertical marker-lines at their intersections.
    strong_rows = [r for r in range(h) if len(rows[r]) >= 2]
    strong_cols = [c for c in range(w) if len(cols[c]) >= 2]
    for r in strong_rows:
        for c in strong_cols:
            near_row = min(abs(x - c) for x in rows[r])
            near_col = min(abs(y - r) for y in cols[c])
            if near_row <= 3 and near_col <= 3:
                for x in range(min(c, min(rows[r])), max(c, max(rows[r])) + 1):
                    if grid[r][x] == background and abs(x - c) <= near_row:
                        out[r][x] = 2
                for y in range(min(r, min(cols[c])), max(r, max(cols[c])) + 1):
                    if grid[y][c] == background and abs(y - r) <= near_col:
                        out[y][c] = 2

    return out
